class Event:
    'An event blocks coroutines until its internal flag is set to True.\n\n    Similar to `threading.Event`.\n\n    A coroutine can wait for an event to be set. Once it is set, calls to\n    ``yield event.wait()`` will not block unless the event has been cleared:\n\n    .. testcode::\n\n        from tornado import gen\n        from tornado.ioloop import IOLoop\n        from tornado.locks import Event\n\n        event = Event()\n\n        async def waiter():\n            print("Waiting for event")\n            await event.wait()\n            print("Not waiting this time")\n            await event.wait()\n            print("Done")\n\n        async def setter():\n            print("About to set the event")\n            event.set()\n\n        async def runner():\n            await gen.multi([waiter(), setter()])\n\n        IOLoop.current().run_sync(runner)\n\n    .. testoutput::\n\n        Waiting for event\n        About to set the event\n        Not waiting this time\n        Done\n    '
    def __init__(self) -> None:
        self._value = False
        self._waiters = set()  # type: Set[Future[None]]

    def clear(self) -> None:
        """Reset the internal flag to ``False``.

        Calls to `.wait` will block until `.set` is called.
        """
        self._value = False

    def set(self) -> None:
        """Set the internal flag to ``True`` and wake up all coroutines waiting on this event."""
        if not self._value:
            self._value = True
            for waiter in self._waiters:
                waiter.set_result(None)
            self._waiters.clear()

    def wait(self) -> Future[None]:
        """Wait until the internal flag is set to ``True``.

        If the flag is already set, this method will return immediately. Otherwise, it will block the coroutine until the event is set.

        Returns:
            A `Future` object that resolves when the event is set.
        """
        if self._value:
            return Future()
        waiter = Future()
        self._waiters.add(waiter)
        try:
            yield waiter
        finally:
            self._waiters.remove(waiter)
```

