def _convert_entity(m: typing.Match) -> str:
    """
    Converts a match object representing an HTML entity to its corresponding Unicode character or standard entity.

    Parameters:
        m (typing.Match): A match object from a regular expression search, expected to have groups where the first group is "#" and the second group represents either a hexadecimal number starting with "x" or a decimal number.

    Returns:
        str: The Unicode character if possible, otherwise the standard entity representation.

    Examples:
        >>> _convert_entity(re.match(r'(&#(\d+)|#(\d{1,5})|([a-zA-Z]+));', '&amp;'))
        '&'
        >>> _convert_entity(re.match(r'(&#(\d+)|#(\d{1,5})|([a-zA-Z]+));', '&#160;'))
        ' '
        >>> _convert_entity(re.match(r'(&#(\d+)|#(\d{1,5})|([a-zA-Z]+));', '&#x8F;'))
        ''
    """
    if m.group(1) == "#":
        try:
            if m.group(2)[:1].lower() == "x":
                return chr(int(m.group(2)[1:], 16))
            else:
                return chr(int(m.group(2)))
        except ValueError:
            return "&#%s;" % m.group(2)
    try:
        return _HTML_UNICODE_MAP[m.group(2)]
    except KeyError:
        return "&%s;" % m.group(2)
```

