class _RequestProxy:
    'Combines an object with a dictionary of defaults.\n\n    Used internally by AsyncHTTPClient implementations.\n    '
    def __init__(
        self, request: HTTPRequest, defaults: Optional[Dict[str, Any]]
    ) -> None:
        self.request = request
        self.defaults = defaults

    def __getattr__(self, name: str) -> Any:
        """
        Handles the retrieval of attributes from an object's `request` and `defaults` properties.

        This method is called when an attribute requested on the instance cannot be found directly or in the request property. It first checks if the attribute exists in the `request` property, then falls back to checking the `defaults` dictionary if available. If neither source contains the requested attribute, it returns `None`.

        Parameters:
            name (str): The name of the attribute being retrieved.

        Returns:
            Any: The value of the requested attribute from either `request` or `defaults`, or None if the attribute is not found in either location.
        """
        request_attr = getattr(self.request, name)
        if request_attr is not None:
            return request_attr
        elif self.defaults is not None:
            return self.defaults.get(name, None)
        else:
            return None
