class SSLIOStream:
    """A utility class to write to and read from a non-blocking SSL socket.

    If the socket passed to the constructor is already connected, it should be wrapped with::

        ssl.wrap_socket(sock, do_handshake_on_connect=False, **kwargs)

    before constructing the `SSLIOStream`. Unconnected sockets will be wrapped when `IOStream.connect` is finished.

    The primary purpose of this class is to facilitate communication over SSL/TLS encrypted sockets by providing methods for writing and reading data in a non-blocking manner. It allows for custom SSL options to be specified, enabling configuration tailored to specific security requirements.

    Parameters:
        *args (Any): Positional arguments to pass to the parent class constructor.
        **kwargs (Any): Keyword arguments including ``ssl_options``, which may either be an `ssl.SSLContext` object or a dictionary of keywords arguments for `ssl.wrap_socket`.

    Examples:
        To create an SSLIOStream with default settings, you can use the following code::

            sock = ssl.wrap_socket(sock, do_handshake_on_connect=False, **kwargs)
            ssl_stream = SSLIOStream(sock)

        If you want to specify custom SSL options, you can pass a dictionary of keyword arguments to `ssl.wrap_socket`::

            ssl_options = {
                'cert_reqs': ssl.CERT_REQUIRED,
                'ca_certs': '/path/to/cacerts.pem'
            }
            sock = ssl.wrap_socket(sock, do_handshake_on_connect=False, **kwargs)
            ssl_stream = SSLIOStream(sock, ssl_options=ssl_options)
    """
    socket = None
    def __init__(self, *args: Any, **kwargs: Any) -> None:
        """The ``ssl_options`` keyword argument may either be an `ssl.SSLContext` object or a dictionary of keywords arguments for `ssl.wrap_socket`.

        This method initializes the SSLIOStream instance with optional SSL options and sets up necessary attributes for handling SSL handshakes. If the provided socket is already connected, it initiates the SSL handshake process.

        Parameters:
            *args (Any): Positional arguments to pass to the parent class constructor.
            **kwargs (Any): Keyword arguments including ``ssl_options``, which may either be an `ssl.SSLContext` object or a dictionary of keywords arguments for `ssl.wrap_socket`.
        """
        self._ssl_options = kwargs.pop("ssl_options", _client_ssl_defaults)
        super().__init__(*args, **kwargs)
        self._ssl_accepting = True
        self._handshake_reading = False
        self._handshake_writing = False
        self._server_hostname = None  # type: Optional[str]

        # If the socket is already connected, attempt to start the handshake.
        try:
            self.socket.getpeername()
        except socket.error:
            pass
        else:
            # Indirectly start the handshake, which will run on the next IOLoop iteration and then the real IO state will be set in _handle_events.
            self._add_io_state(self.io_loop.WRITE)

    def _do_ssl_handshake(self) -> None:
        """Initiates an SSL handshake on the socket.

        This method performs the SSL handshake by calling `socket.do_handshake()`. It handles different SSL errors, including those indicating a need to read or write, and raises appropriate exceptions for connection resets or other critical errors. If the handshake is successful, it updates internal state to reflect that SSL is no longer accepting new connections.
        """
        try:
            self._handshake_reading = False
            self._handshake_writing = False
            self.socket.do_handshake()
        except ssl.SSLError as err:
            if err.args[0] == ssl.SSL_ERROR_WANT_READ:
                self._handshake_reading = True
                return
            elif err.args[0] == ssl.SSL_ERROR_WANT_WRITE:
                self._handshake_writing = True
                return
            elif err.args[0] in (ssl.SSL_ERROR_EOF, ssl.SSL_ERROR_ZERO_RETURN):
                return self.close(exc_info=err)
            elif err.args[0] == ssl.SSL_ERROR_SSL:
                try:
                    peer = self.socket.getpeername()
                except Exception:
                    peer = "(not connected)"
                gen_log.warning("SSL Error on %s %s: %s", self.socket.fileno(), peer, err)
                return self.close(exc_info=err)
            raise
        except ssl.CertificateError as err:
            # CertificateError can happen during handshake (hostname verification) and should be passed to user. Starting in Python 3.7, this error is a subclass of SSLError and will be handled by the previous block instead.
            return self.close(exc_info=err)
        except socket.error as err:
            # Some port scans (e.g. nmap in -sT mode) have been known to cause do_handshake to raise EBADF and ENOTCONN, so make those errors quiet as well.
            if self._is_connreset(err) or err.args[0] in (0, errno.EBADF, errno.ENOTCONN):
                return self.close(exc_info=err)
            raise
        except AttributeError as err:
            # On Linux, if the connection was reset before the call to wrap_socket, do_handshake will fail with an AttributeError.
            return self.close(exc_info=err)
        else:
            self._ssl_accepting = False
            if not self._verify_cert(self.socket.getpeercert()):
                self.close()
                return
            self._finish_ssl_connect()
```

