            def render(self):
                return str(self.current_user)

        loader = DictLoader({
            "without_user.html": "",
            "with_user.html": "{{ current_user }}",
            "without_user_module.html": "{% module WithoutUserModule() %}",
            "with_user_module.html": "{% module WithUserModule() %}",
        })
